def simQ(p, d):
    t=d['time_s']; V=d['voltage_pu']; th=d['bus_angle_rad']; Vs=d['voltage_setpoint_pu']
    Q0=d['reactive_power_pu'][0]; V0=V[0]
    n=len(t); Q=np.empty(n); x=np.zeros(2); Q[0]=Q0
