import pandas as pd,numpy as np,glob,os
from scipy.signal import lfilter
files=sorted(glob.glob('train/*.csv'))
Ds={os.path.basename(f)[:-4]:pd.read_csv(f) for f in files}
def fitQ(L, Tm, keys, use_int=True):
    rows=[];ys=[]
    for k in keys:
        d=Ds[k]; t=d.time_s.values; dt=t[1]-t[0]
        V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; Q=d.reactive_power_pu.values
        Vf=lfilter([dt/ (Tm+dt)],[1,-Tm/(Tm+dt)],V-V[0]) if Tm>0 else V-V[0]  # lagged V dev
        e=(Vs-Vs[0])-Vf
        # integrator X' = Ki*e - L X  discrete exact-ish via lfilter (Euler-equivalent): X_k = a X_{k-1} + dt*Ki*e_{k-1}
        a=np.exp(-L*dt) if L>0 else 1.0
        Xi=lfilter([dt*(1 if True else 0)],[1,-a],e) if L>=0 else None  # per unit Ki, input e
        rows.append(np.column_stack([e, Xi])); ys.append(Q-Q[0])
    X=np.vstack(rows); Y=np.concatenate(ys)
    c=np.linalg.lstsq(X,Y,rcond=None)[0]
    return c, np.sqrt(np.mean((X@c-Y)**2))
best=[]
for L in [0,0.05,0.2,0.5,1,2,5,10]:
    for Tm in [0,0.005,0.02,0.05]:
        c,r=fitQ(L,Tm,list(Ds.keys()))
        best.append((r,L,Tm,c))
best.sort(key=lambda z:z[0])
for b in best[:8]: print(b[0],b[1],b[2],np.round(b[3],4))

