Ds={os.path.basename(f)[:-4]:pd.read_csv(f) for f in files}
def stat(keys, cols):
    X=[];Y=[]
    for k in keys:
        d=Ds[k]
        M=np.column_stack([d.voltage_pu-d.voltage_pu[0], d.voltage_setpoint_pu-d.voltage_setpoint_pu[0], d.bus_angle_rad-d.bus_angle_rad[0], d.active_power_pu-d.active_power_pu[0]])
        X.append(np.column_stack([M[:,cols], np.ones(len(d))])); Y.append(d.reactive_power_pu-d.reactive_power_pu[0])
    X=np.vstack(X);Y=np.concatenate(Y); c=np.linalg.lstsq(X,Y,rcond=None)[0]
    return c, np.sqrt(np.mean((X@c-Y)**2))
